    public sealed class TropicalEnvironment081Tests
    {
        // Frozen ACTUAL pre-candidate0.23 ShoreBaseline1, source825d44787c...
        // and original diagnostic eab0bb005d...; never generated by current art.
        const string OriginalWater="2772addadc9bdbdd2d840b6c63f2e6c1a17044ec97baacd199f191f7b1b467de";
        const string OriginalBridges="d062f4260256cdf56018f9965b645b06dc31140ed565948bc0cbd4b0e0fbdfe8";
        const string OriginalMasks="d97780e7c74af166c7064afcac723833f0ba118b3cce63ae2090f92c853e239d";
        const string OriginalQuery="302f3c2edf3c7fb5ae74fe31cb9bad4f4412c5091a39411513f543acb7a725b0";
        GameObject stage;World world;Transform terrain;Mesh ground,water;
        [SetUp] public void SetUp()
        {
            world=new World(Catalog.Load(),42,"coast","ottoman",5,MapTopology.Tropical);
            stage=new GameObject("081 strict actual Tropical environment");terrain=WaterPresentation.BuildTerrain(stage.transform,world);
            ground=terrain.Find("Continuous sculpted land and river bed").GetComponent<MeshFilter>().sharedMesh;
            water=terrain.Find("Continuous navigable river").GetComponent<MeshFilter>().sharedMesh;
        }
        [TearDown] public void TearDown(){if(stage!=null)UnityEngine.Object.DestroyImmediate(stage);}
        [Test] public void RealOneMeterGroundKeepsFrozenWaterBridgesAndNavigationMasks()
        {
            string before=JsonUtility.ToJson(world.CaptureState());Assert.AreEqual("0.25.0",Application.version);
            Assert.AreEqual(16641,ground.vertexCount);Assert.AreEqual(32768,ground.triangles.Length/3);
            Assert.AreEqual(OriginalWater,MeshHash(water));Assert.AreEqual(OriginalBridges,BridgeHash(terrain));Assert.AreEqual(OriginalMasks,GridHash(world,false));
            Assert.AreNotEqual(OriginalQuery,GridHash(world,true),"A physical profile change, not only a renamed tropical palette");
            var v=ground.vertices;var triangles=ground.triangles;var colors=ground.colors;var uv=ground.uv;int cursor=0;
            Assert.AreEqual(v.Length,colors.Length);Assert.AreEqual(v.Length,uv.Length);
            for(int z=0;z<129;z++)for(int x=0;x<129;x++)
            {int i=x+z*129;var p=new Vector2(x,z);Assert.AreEqual(new Vector3(x,world.Layout.BankHeight(p),z),v[i]);EqualColor(world.Layout.BankLayers(p),colors[i]);Assert.AreEqual(p/128,uv[i]);}
            for(int z=0;z<128;z++)for(int x=0;x<128;x++){int a=x+z*129,b=a+129,c=b+1,d=a+1;foreach(int expected in new[]{a,b,c,a,c,d})Assert.AreEqual(expected,triangles[cursor++]);}
            Assert.AreEqual(before,JsonUtility.ToJson(world.CaptureState()));TestContext.WriteLine("Actual Tropical retained grid129/16641vertices/32768triangles; frozen water/bridge/navigation masks exact");
        }
        [Test] public void AllRealWaterEdgeTrianglesStayWithinTheOriginalTwoMillimeterLimit()
        {
            string before=JsonUtility.ToJson(world.CaptureState());var v=water.vertices;var g=ground.vertices;int samples=0,excluded=0,queryHigh=0,occlusions=0;float max=0;
            Assert.AreEqual(world.Layout.Channels.Single().Centers.Length*5,v.Length);
            for(int segment=0;segment<v.Length/5-1;segment++)foreach(int row in new[]{0,4})for(int quarter=0;quarter<=4;quarter++)
            {
                samples++;var a=v[segment*5+row];var b=v[(segment+1)*5+row];if(OnBorder(a)||OnBorder(b)||new Vector2(a.x-b.x,a.z-b.z).sqrMagnitude<.00000001f){excluded++;continue;}
                var p=Vector3.Lerp(a,b,quarter*.25f);var xz=new Vector2(p.x,p.z);float query=world.Layout.BankHeight(xz),plane=Plane(g,129,xz),clearance=plane-p.y;
                if(query>p.y)queryHigh++;if(query<=p.y&&clearance>.002f)occlusions++;max=Mathf.Max(max,clearance);
            }
            Assert.AreEqual(3340,samples);Assert.AreEqual(410,excluded);Assert.AreEqual(2930,samples-excluded);Assert.AreEqual(0,queryHigh);Assert.AreEqual(0,occlusions,"No newly introduced>2mm triangle-only water occlusion anywhere unclamped");Assert.LessOrEqual(max,.002f);
            Assert.AreEqual(before,JsonUtility.ToJson(world.CaptureState()));TestContext.WriteLine("Actual Tropical water edges:2930unclamped/queryHigh="+queryHigh+" triangleOcclusions="+occlusions+" maxPositiveClearance="+max.ToString("R"));
        }
        [Test] public void ActualTownBridgeDockExitAndLandingPadsKeepHistoricalBankProfiles()
        {
            string before=JsonUtility.ToJson(world.CaptureState());int protectedSamples=0;
            Action<Vector2> historical=p=>{Assert.AreEqual(0,world.Layout.TropicalPreservationWeight081(p),.000001f);Assert.AreEqual(HistoricalHeight(world.Layout,p),world.Layout.BankHeight(p),.000001f);EqualColor(HistoricalLayers(world.Layout,p),world.Layout.BankLayers(p));protectedSamples++;};
            foreach(var start in world.Layout.Starts)for(int y=-10;y<=10;y++)for(int x=-10;x<=10;x++)if(x*x+y*y<=100)historical(start.Town+new Vector2(x,y));
            foreach(var span in world.Layout.Bridges)foreach(float across in new[]{-span.HalfLength-span.RampLength,-span.HalfLength,0,span.HalfLength,span.HalfLength+span.RampLength})foreach(float along in new[]{-span.HalfWidth,0,span.HalfWidth})historical(span.Point(across,along));
            foreach(var bank in world.Layout.DockSites)foreach(var dock in bank)
            {
                var forward=world.Layout.WaterDirection(dock);var side=new Vector2(-forward.y,forward.x);
                foreach(float x in new[]{-2f,0,2f,5f})foreach(float y in new[]{-2f,0,2f})historical(dock+forward*x+side*y);
                foreach(float x in new[]{5.15f,6.4f,7.65f})foreach(float y in new[]{-1.25f,0,1.25f})historical(dock+forward*x+side*y);
            }
            for(int bank=0;bank<2;bank++)for(int landing=0;landing<2;landing++)for(int y=-6;y<=6;y++)for(int x=-6;x<=6;x++)if(x*x+y*y<=36)historical(TropicalBayContent081.Landing(bank,landing)+new Vector2(x,y)*.5f);
            Assert.Greater(protectedSamples,1000);Assert.AreEqual(before,JsonUtility.ToJson(world.CaptureState()));TestContext.WriteLine("Actual protected historical profile samples="+protectedSamples);
        }
        [Test] public void BothDeclaredBayNeighborhoodsHaveBroaderLowBeachAndModestDryShoulder()
        {
            string before=JsonUtility.ToJson(world.CaptureState());var centers=new[]{new Vector2(62,64),new Vector2(89,68)};
            var headlands=new[]{new Vector2(56,66),new Vector2(92,57)};
            for(int bank=0;bank<2;bank++)
            {
                Assert.AreEqual(centers[bank],TropicalBayContent081.Region(bank).BeachCenter);Assert.AreEqual(headlands[bank],TropicalBayContent081.Region(bank).HeadlandCenter);int low=0,raised=0;
                for(int y=-24;y<=24;y++)for(int x=-24;x<=24;x++)
                {
                    var p=centers[bank]+new Vector2(x,y)*.5f;float distance=world.Layout.SignedBankDistance(p);if(distance<=0)continue;
                    float delta=world.Layout.BankHeight(p)-HistoricalHeight(world.Layout,p);if(delta<-.005f)low++;
                    var h=headlands[bank]+new Vector2(x,y)*.5f;if(world.Layout.SignedBankDistance(h)>0&&world.Layout.BankHeight(h)-HistoricalHeight(world.Layout,h)>.005f)raised++;
                }
                Assert.Greater(low,12,"Meaningful low-beach samples in both independently authored neighborhoods");Assert.Greater(raised,12,"A modest physical dry shoulder, not only a material tint");TestContext.WriteLine("Actual Tropical bank="+bank+" broadBeachSamples="+low+" shoulderSamples="+raised);
            }
            float maxGradient=0,maxDryHeight=0;const float step=.25f;
            for(int z=0;z<512;z++)for(int x=0;x<512;x++)
            {var p=new Vector2(x*step,z*step);float h=world.Layout.BankHeight(p);if(!world.Layout.IsWater(p))maxDryHeight=Mathf.Max(maxDryHeight,h);maxGradient=Mathf.Max(maxGradient,Mathf.Abs(world.Layout.BankHeight(p+Vector2.right*step)-h)/step,Mathf.Abs(world.Layout.BankHeight(p+Vector2.up*step)-h)/step);}
            Assert.LessOrEqual(maxGradient,.4f);Assert.LessOrEqual(maxDryHeight,.14001f);Assert.AreEqual(before,JsonUtility.ToJson(world.CaptureState()));TestContext.WriteLine("Actual sampled quarter-meter gradient="+maxGradient.ToString("R")+" maxDryBankHeight="+maxDryHeight.ToString("R"));
        }
        [Test] public void BothLandmarkBatchesUseFogAndLaterConstructionWithinTheEightClusterBudget()
        {
            var visibility=terrain.GetComponent<RiverSceneryVisibility>();Assert.IsNotNull(visibility);Assert.That(visibility.ClusterCount,Is.InRange(2,8));
            for(int bank=0;bank<2;bank++)
            {
                var p=TropicalBayContent081.Region(bank).VegetationCenter;
                var landmark=terrain.GetComponentsInChildren<MeshFilter>(true).Single(f=>Vector2.Distance(new Vector2(f.transform.localPosition.x,f.transform.localPosition.z),p)<.00001f);
                var renderer=landmark.GetComponent<MeshRenderer>();Assert.IsNotNull(renderer);Assert.IsFalse(renderer.enabled,"Unrevealed headland props must not reveal the coastline");
                Assert.AreSame(landmark.sharedMesh,landmark.GetComponent<ProceduralMeshLifetime>().OwnedMesh);Assert.IsEmpty(landmark.GetComponentsInChildren<Collider>(true));Assert.LessOrEqual(landmark.sharedMesh.bounds.max.y,3.1f);
                world.Fog.Reveal(0,p,6);visibility.Refresh(true);Assert.IsTrue(renderer.enabled);
                var house=world.Spawn("house",0,p);visibility.Refresh(true);Assert.IsFalse(renderer.enabled,"Later real building footprint hides the whole natural batch");
                world.Remove(house);visibility.Refresh(true);Assert.IsTrue(renderer.enabled,"Revealed unoccupied landmark returns after ordinary removal");
            }
            TestContext.WriteLine("Actual Tropical visibility clusters="+visibility.ClusterCount+"; both original landmark batches fog/occupancy-gated; controlled Spawn/Remove fixture, not paid placement");
        }
        [UnityTest] public IEnumerator OwnedTropicalTerrainAndLandmarkMeshesReleaseAfterDestruction()
        {
            var meshes=terrain.GetComponentsInChildren<ProceduralMeshLifetime>(true).Select(p=>p.OwnedMesh).Where(m=>m!=null).Distinct().ToArray();Assert.Greater(meshes.Length,6);
            UnityEngine.Object.Destroy(stage);stage=null;yield return null;yield return null;Assert.IsTrue(meshes.All(m=>m==null));TestContext.WriteLine("Actual Tropical owned meshes released="+meshes.Length);
        }
        static float HistoricalHeight(MapLayout layout,Vector2 p)
        {float distance=layout.SignedBankDistance(p);return distance<=0?Mathf.Lerp(layout.WaterHeight-.02f,-.9f,Mathf.SmoothStep(0,1,-distance/4)):(layout.WaterHeight-.02f)*(1-Mathf.SmoothStep(0,1,distance/3));}
        static Color HistoricalLayers(MapLayout layout,Vector2 p)
        {float d=layout.SignedBankDistance(p),noise=Mathf.PerlinNoise(p.x*.13f+3,p.y*.11f+8)-.5f;float damp=1-Mathf.SmoothStep(0,1,(d-.25f-noise*.25f)/2.6f),shoulder=1-Mathf.SmoothStep(0,1,(d-1.5f-noise*.65f)/4),sand=(1-damp)*shoulder;return new Color(damp,sand,1-damp-sand,1);}
        static void EqualColor(Color expected,Color actual){Assert.AreEqual(expected.r,actual.r,.000001f);Assert.AreEqual(expected.g,actual.g,.000001f);Assert.AreEqual(expected.b,actual.b,.000001f);Assert.AreEqual(expected.a,actual.a,.000001f);}
        static bool OnBorder(Vector3 p)=>p.x<=.0001f||p.x>=127.9999f||p.z<=.0001f||p.z>=127.9999f;
        static float Plane(Vector3[] v,int count,Vector2 p)
        {
            float cell=128f/(count-1),px=Mathf.Clamp(p.x/cell,0,count-1),pz=Mathf.Clamp(p.y/cell,0,count-1);int x=Mathf.Min(count-2,Mathf.FloorToInt(px)),z=Mathf.Min(count-2,Mathf.FloorToInt(pz));int a=x+z*count,b=a+count,c=b+1,d=a+1;float tx=px-x,tz=pz-z;
            var p0=v[a];var p1=v[tz>=tx?b:c];var p2=v[tz>=tx?c:d];float denominator=(p1.z-p2.z)*(p0.x-p2.x)+(p2.x-p1.x)*(p0.z-p2.z);Assert.Greater(Mathf.Abs(denominator),.000001f);
            float w0=((p1.z-p2.z)*(p.x-p2.x)+(p2.x-p1.x)*(p.y-p2.z))/denominator,w1=((p2.z-p0.z)*(p.x-p2.x)+(p0.x-p2.x)*(p.y-p2.z))/denominator;return w0*p0.y+w1*p1.y+(1-w0-w1)*p2.y;
        }
        static string GridHash(World world,bool heights)
        {
            using(var stream=new MemoryStream())using(var w=new BinaryWriter(stream))
            {for(int z=0;z<=256;z++)for(int x=0;x<=256;x++){var p=new Vector2(x*.5f,z*.5f);w.Write(p.x);w.Write(p.y);if(heights){w.Write(world.Layout.BankHeight(p));var c=world.Layout.BankLayers(p);w.Write(c.r);w.Write(c.g);w.Write(c.b);w.Write(c.a);}else{w.Write(world.Layout.IsWater(p));w.Write(world.Layout.IsBridge(p));w.Write(world.Layout.IsBridgeApproach(p));w.Write(world.Layout.IsBridgeSideBarrierCell(p));w.Write(world.Navigation.IsWalkable(p,0));w.Write(world.WaterNavigation.IsWalkable(p,0));}}w.Flush();return Hash(stream.ToArray());}
        }
        static string BridgeHash(Transform terrain)
        {
            using(var stream=new MemoryStream())using(var w=new BinaryWriter(stream))
            {foreach(Transform child in terrain)if(child.GetComponentInChildren<MeshFilter>()!=null&&child.name.StartsWith("Raised crossing ",StringComparison.Ordinal))foreach(var f in child.GetComponentsInChildren<MeshFilter>(true)){w.Write(child.name);w.Write(MeshHash(f.sharedMesh));for(int i=0;i<16;i++)w.Write(f.transform.localToWorldMatrix[i]);foreach(var m in f.GetComponent<MeshRenderer>().sharedMaterials)w.Write(m.name);}w.Flush();return Hash(stream.ToArray());}
        }
        static string MeshHash(Mesh mesh)
        {
            using(var stream=new MemoryStream())using(var w=new BinaryWriter(stream))
            {w.Write(mesh.vertexCount);w.Write((int)mesh.indexFormat);w.Write(mesh.subMeshCount);foreach(var v in mesh.vertices){w.Write(v.x);w.Write(v.y);w.Write(v.z);}foreach(var n in mesh.normals){w.Write(n.x);w.Write(n.y);w.Write(n.z);}foreach(var t in mesh.tangents){w.Write(t.x);w.Write(t.y);w.Write(t.z);w.Write(t.w);}foreach(var c in mesh.colors){w.Write(c.r);w.Write(c.g);w.Write(c.b);w.Write(c.a);}for(int i=0;i<8;i++){var uv=new List<Vector4>();mesh.GetUVs(i,uv);w.Write(uv.Count);foreach(var t in uv){w.Write(t.x);w.Write(t.y);w.Write(t.z);w.Write(t.w);}}for(int i=0;i<mesh.subMeshCount;i++){w.Write((int)mesh.GetTopology(i));var t=mesh.GetIndices(i);w.Write(t.Length);foreach(int index in t)w.Write(index);}var b=mesh.bounds;foreach(float f in new[]{b.center.x,b.center.y,b.center.z,b.size.x,b.size.y,b.size.z})w.Write(f);w.Flush();return Hash(stream.ToArray());}
        }
        static string Hash(byte[] value)
        {using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(value)).Replace("-", "").ToLowerInvariant();}
    }
